select COALESCE(sum(amount), 0) from tb_order
where status = #{status}
  and create_time >= #{beginTime}
  and create_time < #{endTime}

select count(*) from tb_order
where status = #{status}
  and create_time >= #{beginTime}
  and create_time < #{endTime}

select node_name as nodeName, sum(amount) as revenue
from tb_order
where status = #{status}
  and create_time >= #{beginTime}
  and create_time < #{endTime}
group by node_id, node_name
order by revenue desc limit 10

select sku_name as skuName, count(*) as sales
from tb_order
where status = #{status}
  and create_time >= #{beginTime}
  and create_time < #{endTime}
group by sku_id, sku_name
order by sales desc limit 10
